class Blueprint:
    def __init__(self, name: str, import_name: str):
        self.name = name
        self.import_name = import_name

class Flask:
    def __init__(self, name: str):
        self.name = name
        self.blueprints = {}

    def register_blueprint(self, bp: Blueprint):
        if bp.name in self.blueprints and self.blueprints[bp.name] is not bp:
            raise ValueError(f"Blueprint name '{bp.name}' is already registered with a different instance.")
        self.blueprints[bp.name] = bp
